def merge_k_sorted(lists: List[List[int]]) -> List[int]:
    if not lists:
        return None

    min_heap = []
    for lst in lists:
        if lst:
            heapq.heappush(min_heap, (lst[0], lst, 0))

    merged_list = []
    while min_heap:
        value, lst, idx = heapq.heappop(min_heap)
        merged_list.append(value)
        if idx + 1 < len(lst):
            heapq.heappush(min_heap, (lst[idx + 1], lst, idx + 1))

    return merged_list

