class RateLimiter:
    def __init__(self, max_calls: int, period_seconds: float):
        if max_calls <= 0 or period_seconds <= 0:
            return None
        self.max_calls = max_calls
        self.period_seconds = period_seconds
        self.call_times = deque()

    def allow(self, timestamp: float) -> bool:
        if not self.call_times:
            self.call_times.append(timestamp)
            return True

        # Remove timestamps that are outside the sliding window
        while self.call_times and timestamp - self.call_times[0] > self.period_seconds:
            self.call_times.popleft()

        # If the number of calls within the window is less than max_calls, allow the call
        if len(self.call_times) < self.max_calls:
            self.call_times.append(timestamp)
            return True
        else:
            return False

